import sys
from collections import deque

def is_connected(grid):
    n, m = len(grid), len(grid[0])
    visited = [[False] * m for _ in range(n)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def bfs(start):
        queue = deque([start])
        visited[start[0]][start[1]] = True
        count = 0
        while queue:
            x, y = queue.popleft()
            count += 1
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '#' and not visited[nx][ny]:
                    visited[nx][ny] = True
                    queue.append((nx, ny))
        return count

    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                start = (i, j)
                break
        if start:
            break

    component_size = bfs(start)
    total_painted = sum(row.count('#') for row in grid)
    return component_size == total_painted

def remove_squares(grid, k):
    n, m = len(grid), len(grid[0])
    painted = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == '#']

    for combination in combinations(painted, k):
        new_grid = [row[:] for row in grid]
        for x, y in combination:
            new_grid[x][y] = '.'
        if not is_connected(new_grid):
            return True
    return False

def main():
    import sys
    import itertools
    input = sys.stdin.read().split()
    n, m = map(int, input[:2])
    grid = input[2:]

    if not is_connected(grid):
        print(0)
        return

    for k in range(1, n * m + 1):
        if remove_squares(grid, k):
            print(k)
            return

    print(-1)

if __name__ == "__main__":
    main()
